inline const std::map<std::wstring,Row>& catalog(){
 static const std::map<std::wstring,Row> data=[](){
  static std::vector<std::vector<std::wstring>> storage;std::map<std::wstring,Row> result;
  auto parse=[&](const wchar_t* blob){const wchar_t* p=blob;const wchar_t* start=p;std::vector<std::wstring> fields;
   for(;*p;++p){if(*p==0x1f||*p==0x1e){fields.emplace_back(start,p);start=p+1;if(*p==0x1e){storage.push_back(std::move(fields));fields.clear();}}}};
  parse(extraTranslationBlob());parse(translationBlob());
  for(auto& values:storage){if(values.size()!=15)continue;Row row={};for(int i=0;i<15;++i)row.text[i]=values[i].c_str();result.emplace(values[0],row);}return result;
 }();return data;
}

inline const std::map<std::wstring,const Row*>& reverseCatalog(){static const std::map<std::wstring,const Row*> data=[](){std::map<std::wstring,const Row*> result;for(auto& row:catalog())for(int i=1;i<15;++i)if(*row.second.text[i])result.emplace(row.second.text[i],&row.second);return result;}();return data;}
struct TrieNode {std::map<wchar_t,size_t> children;const Row* value=nullptr;};
inline const std::vector<TrieNode>& trie(){static const std::vector<TrieNode> data=[](){std::vector<TrieNode> nodes(1);for(auto& row:catalog()){if(row.first.find(L'\0')!=std::wstring::npos)continue;size_t at=0;for(auto c:row.first){auto it=nodes[at].children.find(c);if(it==nodes[at].children.end()){size_t next=nodes.size();nodes[at].children[c]=next;nodes.emplace_back();at=next;}else at=it->second;}nodes[at].value=&row.second;}return nodes;}();return data;}
inline bool hasHan(const std::wstring& text){for(auto c:text)if(c>=0x3400&&c<=0x9fff)return true;return false;}
inline const std::wregex& printfPattern(){static const std::wregex pattern(L"%([-+0-9.*hlz]*[sSdDfFuUiIxX]|%)");return pattern;}
struct MessageTemplate {std::wregex pattern;const Row* row;int slots;};
inline const std::vector<MessageTemplate>& messageTemplates(){static const std::vector<MessageTemplate> values=[](){std::vector<MessageTemplate> result;for(auto& entry:catalog()){
 if(entry.first.find(L'%')==std::wstring::npos||entry.first.find(L".png")!=std::wstring::npos)continue;
 std::wstring pattern=L"^";int count=0;for(size_t i=0;i<entry.first.size();){std::wsmatch match;auto remaining=entry.first.substr(i);if(entry.first[i]==L'%'&&std::regex_search(remaining,match,printfPattern(),std::regex_constants::match_continuous)){if(match.str()==L"%%")pattern+=L"%";else{pattern+=L"([\\s\\S]*?)";++count;}i+=match.length();}
 else{wchar_t c=entry.first[i++];if(std::wstring(L"\\.^$|()[]{}*+?").find(c)!=std::wstring::npos)pattern+=L'\\';pattern+=c;}}
 if(count)result.push_back({std::wregex(pattern+L"$"),&entry.second,count});}return result;}();return values;}
inline bool formattedMessage(const std::wstring& text,int language,std::wstring& output){for(auto& entry:messageTemplates()){std::wsmatch match;if(!std::regex_match(text,match,entry.pattern))continue;
 std::wstring target=entry.row->text[language];size_t at=0;int slot=1;for(auto it=std::wsregex_iterator(target.begin(),target.end(),printfPattern());it!=std::wsregex_iterator();++it){output+=target.substr(at,size_t(it->position())-at);if(it->str()==L"%%")output+=L'%';else if(slot<=entry.slots)output+=match[slot++].str();at=size_t(it->position()+it->length());}output+=target.substr(at);while(slot<=entry.slots){output+=L" ["+match[slot++].str()+L"]";}return true;}return false;}
inline std::wstring tr(const std::wstring& text){
    int language=current();if(language<0||language>=15||text.empty())return text;
    auto found=catalog().find(text);if(found!=catalog().end())return found->second.text[language];
    if(language==0)return text;
    bool numericToken=text.find_first_of(L"0123456789")!=std::wstring::npos&&text.find_first_of(L" \t\n")==std::wstring::npos;
    if(text.size()>=4&&!numericToken){auto reverse=reverseCatalog().find(text);if(reverse!=reverseCatalog().end())return reverse->second->text[language];}
    // Menu accelerators are separate from the caption, never translated as text.
    auto tab=text.find(L'\t');if(tab!=std::wstring::npos)return tr(text.substr(0,tab))+text.substr(tab);
    if(!hasHan(text))return text;
    static std::map<std::pair<int,std::wstring>,std::wstring> memo;auto key=std::make_pair(language,text);auto hit=memo.find(key);if(hit!=memo.end())return hit->second;
    std::wstring output;if(formattedMessage(text,language,output)){memo.emplace(key,output);return output;}
    const auto& nodes=trie();
    for(size_t i=0;i<text.size();){
        // Filesystem paths and URLs in diagnostics remain verbatim.
        if((i+2<text.size()&&iswalpha(text[i])&&text[i+1]==L':'&&(text[i+2]==L'\\'||text[i+2]==L'/'))||text.compare(i,8,L"https://")==0||text.compare(i,7,L"http://")==0){size_t end=text.find_first_of(L"\r\n\"<>|",i);if(end==std::wstring::npos)end=text.size();output+=text.substr(i,end-i);i=end;continue;}
        size_t at=0,best=i,j=i;const Row* value=nullptr;
        while(j<text.size()){auto next=nodes[at].children.find(text[j]);if(next==nodes[at].children.end())break;at=next->second;++j;if(nodes[at].value){value=nodes[at].value;best=j;}}
        if(value){output+=value->text[language];i=best;}else output+=text[i++];
    }
    if(memo.size()>4096)memo.clear();memo.emplace(std::move(key),output);return output;
}
